python - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png'); g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
print('gray quant',[(q,round(float(np.quantile(g,q)),1)) for q in [0,.05,.1,.25,.5,.75,.9,.95,1]])
# Hough circles
for p2 in [20,30,40,50]:
 cs=cv2.HoughCircles(g,cv2.HOUGH_GRADIENT,dp=1,minDist=30,param1=100,param2=p2,minRadius=20,maxRadius=220)
 print('p2',p2, None if cs is None else np.round(cs[0],1).tolist())
# LSD lines
lsd=cv2.createLineSegmentDetector(1)
lines=lsd.detect(g)[0]
out=[]
if lines is not None:
 for ln in lines[:,0]:
  x1,y1,x2,y2=ln; L=((x2-x1)**2+(y2-y1)**2)**.5
  if L>=20: out.append((round(L,1),tuple(round(float(v),1) for v in ln),round(float(np.degrees(np.arctan2(y2-y1,x2-x1))),1)))
print('lines',len(out))
for z in sorted(out,reverse=True)[:80]:print(z)
PY"
